using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
// Racing line and traffic decisions only. All movement remains four-wheel vehicle physics.
public sealed partial class RoadPilot {
 public bool ClosedCourse;bool initialMerge;public void SeedClosedGrid(bool left){laneShift=left?-3.5f:0;initialMerge=left;}
 float laneShift,blockedFor,passClock,passCooldown;bool merging;FinchVehicle passingCar;
 public bool Passing=>passingCar!=null;public float LaneShift=>laneShift;public float TargetKph{get;private set;}public int Overtakes{get;private set;}
 readonly Collider[] nearby=new Collider[64];const int SenseMask=~((1<<28)|(1<<29)|(1<<31));
 void ResetRaceLine(){initialMerge=false;laneShift=blockedFor=passClock=0;passingCar=null;merging=false;passCooldown=0;}
 Vector3 RoadForward(int i){var d=Path[(i+2)%Path.Length]-Path[i%Path.Length];d.y=0;return d.normalized;}
 bool StraightFor(float meters){var forward=RoadForward(Index);float distance=0;int i=Index;for(int n=0;n<Path.Length-2&&distance<meters;n++){if(Vector3.Angle(forward,RoadForward(i))>16)return false;distance+=Vector3.Distance(Path[i],Path[(i+1)%Path.Length]);i=(i+1)%Path.Length;}return true;}
 float CornerSpeed(){float target=CruiseKph,travel=0;float speed=Car.SpeedKph/3.6f;float horizon=Mathf.Clamp(18+speed*speed/6,35,150);int i=Index;for(int n=0;n<100&&travel<horizon;n++){var a=Path[i%Path.Length];var b=Path[(i+3)%Path.Length];var c=Path[(i+6)%Path.Length];var ab=b-a;var bc=c-b;ab.y=bc.y=0;float angle=Vector3.Angle(ab,bc)*Mathf.Deg2Rad;if(angle>.005f){float radius=(ab.magnitude+bc.magnitude)*.5f/angle;float corner=Mathf.Sqrt(Mathf.Max(3,radius)*(IsRival?4.0f:2.5f));float approach=Mathf.Sqrt(corner*corner+2*(IsRival?4:3)*Mathf.Max(0,travel-5))*3.6f;target=Mathf.Min(target,approach);}travel+=Vector3.Distance(Path[i%Path.Length],Path[(i+2)%Path.Length]);i=(i+2)%Path.Length;}return Mathf.Max(12,target);}
 FinchVehicle LeadInOwnLane(out float gap){gap=40;FinchVehicle lead=null;var forward=RoadForward(Index);var right=Vector3.Cross(Vector3.up,forward);var origin=LanePoint(Index,Lane);int count=Physics.OverlapSphereNonAlloc(Car.transform.position,44,nearby,SenseMask,QueryTriggerInteraction.Ignore);for(int i=0;i<count;i++){var other=nearby[i].GetComponentInParent<FinchVehicle>();if(other==null||other==Car)continue;var relative=other.transform.position-Car.transform.position;float ahead=Vector3.Dot(relative,forward);if(ahead<3||ahead>gap||Mathf.Abs(Vector3.Dot(other.transform.position-origin,right))>1.45f||Vector3.Dot(other.transform.forward,forward)<.65f)continue;gap=ahead;lead=other;}return lead;}
 // Candidate lane must have room behind, ahead and against approaching traffic for the pass duration.
 bool LaneClear(float lane,float behind,float ahead,float duration){var forward=RoadForward(Index);var right=Vector3.Cross(Vector3.up,forward);var center=LanePoint(Index,lane);center+=forward*Vector3.Dot(Car.transform.position-center,forward);center.y=Car.transform.position.y+.9f;int count=Physics.OverlapCapsuleNonAlloc(center-forward*behind,center+forward*ahead,.9f,nearby,SenseMask,QueryTriggerInteraction.Ignore);if(count==nearby.Length)return false;for(int i=0;i<count;i++){var c=nearby[i];if(c.transform.IsChildOf(Car.transform))continue;var other=c.GetComponentInParent<FinchVehicle>();if(other==null)continue;var delta=other.transform.position-center;float along=Vector3.Dot(delta,forward);if(Mathf.Abs(Vector3.Dot(delta,right))>2)continue;float velocity=Vector3.Dot(other.Body.linearVelocity,forward);if(along<0){if(along> -behind||velocity>Car.SpeedKph/3.6f+2&&-along/(velocity-Car.SpeedKph/3.6f)<duration)return false;}else if(velocity< -1){if(along/(Mathf.Max(Car.SpeedKph,CornerSpeed())/3.6f-velocity)<duration+2)return false;}else if(along<ahead)return false;}
 int obstacles=Physics.SphereCastNonAlloc(center,.72f,forward,hits,Mathf.Min(ahead,28),SenseMask,QueryTriggerInteraction.Ignore);for(int i=0;i<obstacles;i++)if(!hits[i].collider.transform.IsChildOf(Car.transform)&&hits[i].normal.y<.7f&&hits[i].collider.GetComponentInParent<FinchVehicle>()==null)return false;return true;}
 void UpdateRaceLine(float dt){passCooldown=Mathf.Max(0,passCooldown-dt);if(!IsRival){laneShift=Mathf.MoveTowards(laneShift,0,dt);return;}float desired=0;if(ClosedCourse&&initialMerge){desired=LaneClear(Lane,13,18,3)?0:-3.5f;laneShift=Mathf.MoveTowards(laneShift,desired,dt*1.7f);if(Mathf.Abs(laneShift)<.05f)initialMerge=false;return;}if(passingCar!=null){passClock+=dt;float ahead=Vector3.Dot(passingCar.transform.position-Car.transform.position,RoadForward(Index));bool clearHome=LaneClear(Lane,13,18,3);bool safePassing=LaneClear(Lane-3.5f,8,Mathf.Clamp(Car.SpeedKph/3.6f*5+65,90,200),4);if(!merging&&(ahead< -10||!safePassing||!StraightFor(35)||passClock>18)&&clearHome){merging=true;if(ahead< -10)Overtakes++;}desired=merging?0:-3.5f;if(merging&&Mathf.Abs(laneShift)<.05f){passingCar=null;passCooldown=3;blockedFor=0;}}
 else if(Lane>1&&Lane<2&&passCooldown<=0&&!Recovering&&StraightFor(60)){float gap;var lead=LeadInOwnLane(out gap);float target=CornerSpeed();if(lead!=null&&lead.SpeedKph<target-7&&gap<35){blockedFor+=dt;float passTime=Mathf.Clamp((gap+15)/Mathf.Max(4,(target-lead.SpeedKph)/3.6f)+4,5,12);float horizon=Mathf.Clamp((target/3.6f+30)*passTime,100,300);if(blockedFor>.4f&&StraightFor(Mathf.Max(60,target/3.6f*passTime))&&LaneClear(Lane-3.5f,15,horizon,passTime)){passingCar=lead;passClock=0;merging=false;desired=-3.5f;}}else blockedFor=0;}
 laneShift=Mathf.MoveTowards(laneShift,desired,dt*1.7f);}
 float FollowTraffic(float target){var origin=Car.transform.position+Car.transform.forward*2.2f+Vector3.up*.8f;float speed=Car.SpeedKph/3.6f;float horizon=Mathf.Max(10,5+speed*1.6f);int count=Physics.SphereCastNonAlloc(origin,.72f,Car.transform.forward,hits,horizon,SenseMask,QueryTriggerInteraction.Ignore);for(int i=0;i<count;i++){var hit=hits[i];if(hit.collider.transform.IsChildOf(Car.transform)||hit.normal.y>.7f)continue;var lead=hit.collider.GetComponentInParent<FinchVehicle>();if(lead==Car)continue;float leadKph=lead==null?0:Mathf.Max(0,Vector3.Dot(lead.Body.linearVelocity,Car.transform.forward)*3.6f);float desiredGap=3+speed*.6f;float follow=Mathf.Max(0,leadKph+(hit.distance-desiredGap)*2.4f);if(hit.distance<2)follow=0;target=Mathf.Min(target,follow);}return target;}
}
}
